// Drive the two real cadence terms over this repo's actual ticks (cron '44 5,17'),
// with dailyHour 5, and print which ticks each one grants.
import { evaluatePrecondition } from '/home/user/Claudinite/packs/claudinite-tasks/public/task-declaration.mjs';

const SCHEDULE = { dailyHour: 5, weeklyDay: 'Sun', monthlyDay: 1 };
const decl = (term) => ({ id: 't', preconditions: [term], trigger: 'schedule' });

// One tick a run: the item is created when the scheduler says yes, and (for this
// demo) closes 20 minutes later. `list` is newest-first, as the collector builds it.
async function simulate(term, ticks) {
  const runs = [];
  const fired = [];
  for (const at of ticks) {
    const v = await evaluatePrecondition(
      { decl: decl(term), terms: new Map() },
      { runs: { list: runs, horizonDays: 40 } },
      {}, null, at, SCHEDULE,
    );
    if (v.run) {
      const createdAt = at;
      const closedAt = new Date(Date.parse(at) + 20 * 60e3).toISOString();
      runs.unshift({ number: runs.length + 1, createdAt, closedAt, park: null });
      fired.push(at);
    }
  }
  return fired;
}

const ticks = [];
for (let day = 1; day <= 7; day += 1) {
  for (const hm of ['05:44', '17:44']) {
    ticks.push(`2026-10-0${day}T${hm}:00Z`);
  }
