1	// The precondition engine (docs/PRINCIPLES.md): may THIS task run now? A
2	// task declares `preconditions` — a list of named conditions — and this module
3	// turns that declaration plus the collected signals into a verdict. Sibling of
4	// merge-policy.mjs beside it, and deliberately its mirror image in two ways:
5	//
6	//   THE LIST IS A CONJUNCTION. `['X', 'Y || Z']` is `X && (Y || Z)`. An automerge
7	//   policy GRANTS, so its comma is a union; preconditions REQUIRE, so the comma
8	//   is `&&` and `||` lives inside one entry. Each field then reads against its
9	//   own English.
10	//
11	//   IT FAILS LOUD, NOT CLOSED. An unresolvable merge policy authorizes nothing,
12	//   which parks a PR in front of a person. An unresolvable precondition that
13	//   declined would be permanent, silent staleness — nothing goes red when a task
14	//   stops running — so an unknown term, a malformed argument or an unreadable
15	//   signal returns `{ error }`, a failed run in the queue's failure lane.
16	//
17	// THE EXPRESSION IS WHAT MUST HOLD, NEVER WHO ASKS (docs/PRINCIPLES.md). The
18	// engine keeps no calendar: every scheduler tick asks every task whose declaration
19	// says `trigger: 'schedule'`, and the cadence such a task keeps is one of its own
20	// conditions, read off its own run history, `schedule:at-most-<cadence>`, beside
21	// whatever else it requires. The same conditions are judged, identically, at the
22	// pick of an item somebody created, so
23	// this module never asks which of the two happened. `none` is retired: a task with
24	// nothing to require states no condition, and the empty expression holds.
25	//
26	// THE VOCABULARY HAS TWO HOMES. The built-ins below are the run-history, movement
27	// and pending-PR conditions every repo shares. A task whose gate is its own ships a
28	// `preconditions.mjs` beside its `task.json` exporting `terms`, resolved after the
29	// built-ins in one flat namespace where a collision is loud — so the declaration
30	// and the gate it names are one directory apart.
31	//
32	// Import-light and pure over the signals: no I/O, so the same evaluation runs at
33	// the scheduler's tick and at the executor's pick.
34	
35	import {
36	  anchorInstant, cadenceOfScheduleArg, scheduleTermFor, AT_MOST_PREFIX, CADENCES,
37	  DUE_TERM, SCHEDULE_TERM, NOT_FAILED_TERM, NOT_PARKED_TERM,
38	} from './calendar.mjs';
39	
40	// The retired empty precondition. The contract's door still strips it from a
41	// declaration that carries a `frequency` (the cadence term takes its place); on
42	// its own it is an error, named below.
43	export const NONE = 'none';
44	
45	const ALTERNATIVE = '||';
46	
47	// How many paths or numbers a term's context names before it says how many it
48	// dropped. A window can carry more files than one session should read, and a
49	// silently truncated list reads as the whole window.
50	export const MAX_CONTEXT_ITEMS = 40;
51	
52	// --- the grammar --------------------------------------------------------------
53	
54	// One term reference: its name, and the inline argument after its first colon
55	// (`commits-under:.claudinite/local`). The rest of the string is the argument
56	// verbatim, so a path argument may itself contain colons.
57	function parseTerm(text) {
58	  const raw = String(text ?? '').trim();
59	  const colon = raw.indexOf(':');
60	  return colon === -1
61	    ? { name: raw, arg: null, text: raw }
62	    : { name: raw.slice(0, colon).trim(), arg: raw.slice(colon + 1).trim(), text: raw };
63	}
64	
65	// Parse a declaration into `{ kind: 'conditions', conditions }` (each condition an
66	// array of alternatives) or `{ kind: 'invalid', reason }`. Names are not resolved
67	// here — that needs the task's own terms, which the static check and the
68	// evaluator each supply.
69	export function parsePreconditions(preconditions) {
70	  const invalid = (reason) => ({ kind: 'invalid', reason });
71	  if (!Array.isArray(preconditions)) {
72	    return invalid('it is not an array of condition strings');
73	  }
74	  if (!preconditions.every((e) => typeof e === 'string' && e.trim() !== '')) {
75	    return invalid('every entry must be a non-empty string');
76	  }
77	  const conditions = preconditions.map((entry) => String(entry).split(ALTERNATIVE).map(parseTerm));
78	  if (conditions.some((alts) => alts.some((t) => t.name === ''))) {
79	    return invalid(`an alternative around "${ALTERNATIVE}" is empty`);
80	  }
81	  if (conditions.flat().some((t) => t.name === NONE)) {
82	    return invalid(`"${NONE}" is retired — a task with no condition states none: leave "preconditions" out, and the task runs only from an item somebody creates. Otherwise state when it runs: a cadence (\`${scheduleTermFor('daily')}\`) or the movement it waits for`);
83	  }
84	  return { kind: 'conditions', conditions };
85	}
86	
87	// The task's own terms, as a Map, from whatever its `preconditions.mjs` exported.
88	// A non-object export is no terms at all rather than a crash; the shape check is
89	// what reports it.
90	export function termsMap(exported) {
91	  if (exported instanceof Map) return exported;
92	  if (exported && typeof exported === 'object') return new Map(Object.entries(exported));
93	  return new Map();
94	}
95	
96	// Resolve a term name: built-ins first, then the task's own.
97	export const resolveTerm = (name, taskTerms) => BUILTIN_TERMS.get(name) ?? taskTerms?.get?.(name) ?? null;
98	
99	// --- the signal union, derived ------------------------------------------------
100	
101	// Every signal the expression's terms read. The collector union cannot disagree
102	// with what the gate actually consults, because it IS what the gate consults —
103	// which a separately declared list could not guarantee.
104	export function preconditionSignals(preconditions, taskTerms) {
105	  const parsed = parsePreconditions(preconditions);
106	  if (parsed.kind !== 'conditions') return [];
107	  const out = new Set();
108	  for (const ref of parsed.conditions.flat()) {
109	    for (const s of resolveTerm(ref.name, taskTerms)?.signals ?? []) out.add(s);
110	  }
111	  return [...out];
112	}
113	
114	// Whether the expression reads the item itself — a term declaring `needsItem`
115	// (the request implementer's `request-eligible`, about one named issue). The
116	// scheduler's own ask has no item, so there is nothing to judge such a task
117	// against at a tick: it runs only from an item somebody created.
118	export function preconditionNeedsItem(preconditions, taskTerms) {
119	  const parsed = parsePreconditions(preconditions);
120	  if (parsed.kind !== 'conditions') return false;
121	  return parsed.conditions.flat().some((ref) => resolveTerm(ref.name, taskTerms)?.needsItem === true);
122	}
123	
124	// --- static validation --------------------------------------------------------
125	
126	// Everything about a declaration that is decidable without signals: the grammar,
127	// the term names, their arguments, and a task-local term shadowing a built-in.
128	// Returns `{ what, fix }` problems — empty means well-formed.
129	export function validatePreconditions(preconditions, taskTerms = new Map()) {
130	  const problems = [];
131	  const bad = (what, fix) => problems.push({ what, fix });
132	  for (const name of taskTerms.keys?.() ?? []) {
133	    if (BUILTIN_TERMS.has(name)) {
134	      bad(`the task's preconditions.mjs redefines the built-in term "${name}"`,
135	        `rename the task-local term — the term namespace is flat, and the built-ins are: ${[...BUILTIN_TERMS.keys()].join(', ')}`);
136	    }
137	  }
138	  const parsed = parsePreconditions(preconditions);
139	  if (parsed.kind === 'invalid') {
140	    bad(`"preconditions" is not a legal expression: ${parsed.reason}`,
141	      `write a list of conditions, all of which must hold — a cadence first where the task keeps one ("${SCHEDULE_TERM}:${AT_MOST_PREFIX}<daily|weekly|monthly>"), then what it waits for, e.g. ["${scheduleTermFor('weekly')}", "substantive-change", "no-open-pr-titled:My sweep"]; a task that runs only from an item somebody creates states no "preconditions" at all`);
142	    return problems;
143	  }

