 85	}
 86	
 87	// --- the cadence terms ----------------------------------------------------------
 88	// How a task states WHEN it runs, inside its own `preconditions`: the queue keeps no
 89	// calendar of its own, so the cadence is one of the task's conditions.
 90	//
 91	//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
 92	//                                this repo's schedule — fixed hours, no drift
 93	//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
 94	//
 95	// Whether a task is asked at all is its `trigger`, not the shape of this list: a
 96	// task nothing asks may still state conditions, which are judged when somebody
 97	// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
 98	//
 99	export const CADENCES = ['daily', 'weekly', 'monthly'];
100	export const DUE_TERM = 'due';
101	export const ELAPSED_TERM = 'last-run-over';
102	export const NOT_FAILED_TERM = 'last-run-not-failed';
103	export const NOT_PARKED_TERM = 'last-run-not-parked';
104	
105	// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
106	const DURATION_RE = /^(\d+)(h|d)$/;
107	export function parseDuration(text) {
108	  const m = DURATION_RE.exec(String(text ?? ''));
109	  if (!m) return null;
110	  const n = Number(m[1]);
111	  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
112	}
113	
114	// The term references an expression carries: each entry split on `||`, each
115	// reference `{ name, arg }` with the argument after the first colon.
116	const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
117	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
118	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
119	
120	// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
121	// 'elapsed', ms, text }`, or null for a task with no cadence term (asked at every
122	// tick while it states any condition, it runs whenever those hold). The first
123	// cadence term wins.
124	export function cadenceOf(preconditions) {
125	  for (const ref of entriesOf(preconditions).flat()) {
126	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
127	    if (ref.name === ELAPSED_TERM) {
128	      const ms = parseDuration(ref.arg);
129	      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
130	    }
131	  }
132	  return null;
133	}
134	
135	// Whether the declaration states any condition at all. Not a scheduling answer on
136	// its own — `trigger` is that. An entry carrying only separators states nothing,
137	// which is why this is not a length test.
138	export const statesConditions = (preconditions) => entriesOf(preconditions).some((alts) => alts.length > 0);
139	
140	// A term gates when it is a whole conjunct of the expression — `['x', …]` gates,
141	// `['due:daily || x']` merely widens.
142	const gatesOn = (preconditions, term) =>
143	  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === term && alts[0].arg === null);
144	
145	// A task stops past its own failure park only when it says so: nothing holds a
146	// task's lane but its own word — `last-run-not-failed` for that park alone, or
147	// `last-run-not-parked`, which holds behind all four and so answers this too.
148	export const holdsOnFailure = (preconditions) =>
149	  gatesOn(preconditions, NOT_FAILED_TERM) || gatesOn(preconditions, NOT_PARKED_TERM);
150	
151	// Whether the declaration holds its lane behind EVERY park, the three a person's
152	// inbox owns included. A reader showing what happens next needs the wider answer
153	// as well: a task held behind an approval park is not being asked on schedule,
154	// and an anchor shown there promises a run the task declines.
155	export const holdsOnAnyPark = (preconditions) => gatesOn(preconditions, NOT_PARKED_TERM);
156	
157	// What the retired `frequency` field always meant, as the term that now says it —
158	// or null for `manual`, which meant no schedule at all and so adds no term.
159	export const cadenceTermFor = (frequency) =>
160	  (frequency === 'manual' ? null : `${DUE_TERM}:${frequency}`);
161	
162	// --- the anchors ---------------------------------------------------------------
163	
164	// One period of a cadence word (`daily`, `weekly`, `monthly`; `manual` has none), in
165	// ms — the coarse step `nextAnchor` walks.
166	export function periodMs(frequency) {
167	  const freq = frequency;
168	  if (freq === 'weekly') return 7 * DAY_MS;
169	  if (freq === 'monthly') return 31 * DAY_MS;
170	  if (freq === 'manual') return null;
171	  return DAY_MS;
172	}
173	
174	// The period a TASK keeps, read off the cadence term its declaration states: a
175	// `due:` cadence's period, a `last-run-over:` duration, and null for a task with
176	// no cadence term (asked at every tick, it runs on movement or when woken).
177	export function taskPeriodMs(decl) {
178	  const cadence = cadenceOf(decl?.preconditions);
179	  if (cadence?.kind === 'due') return periodMs(cadence.cadence);
180	  if (cadence?.kind === 'elapsed') return cadence.ms;
181	  return null;
182	}
183	
184	// The earliest occurrence strictly after `now` — what a rolled item is stamped
185	// with. Derived by walking `mostRecentAnchor` forward rather than by adding a
186	// period: monthly anchors are not a fixed distance apart, and a `daily-2h` whose
187	// instant wraps to the previous calendar day is exactly the case a fixed add gets
188	// wrong. The coarse step is under one period, so the loop advances by at most two
189	// steps and never overshoots an occurrence.
190	export function nextAnchor(frequency, schedule, now) {
191	  if (frequency === 'manual') return null;
192	  const from = mostRecentAnchor(frequency, schedule, now).getTime();
193	  const step = frequency === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
194	  for (let t = from + step; ; t += step) {
195	    const candidate = mostRecentAnchor(frequency, schedule, new Date(t));
196	    if (candidate.getTime() > from) return candidate;
197	  }
198	}

