import re
p='packs/claudinite-dashboard/src/derive/task-calendar.mjs'
s=open(p).read()

# 1. the anchor arithmetic: defaults, weekday table, normalizeSchedule, mostRecentAnchor
start = s.index('// The documented anchor defaults')
end = s.index('// --- the cadence terms ---')
