  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' })), { schedule: null }).run, false);
  assert.match(evaluate(['due:daily'], runs(), { now: null }).error, /no instant/);
});

