attachment.snippet:
1	// The scheduling calendar as the dashboard reads it: which instant a task's window
2	// last opened at or opens next, how long a cadence's period is, and which cadence
3	// term a declaration states. THE DASHBOARD'S OWN COPY of the queue's arithmetic
4	// (`packs/claudinite-tasks/src/contract/calendar.mjs` and `src/items/anchors.mjs`):
5	// packs share no code, so the page talks to the queue only through its vocabulary and
6	// carries the arithmetic it renders with. `test/task-calendar-drift.test.mjs` runs both
7	// sides over the same instants and declarations and fails the moment they disagree.
8	//
9	// All times are UTC. `now` is always injected, so every answer is deterministic.
10	
11	const HOUR_MS = 3600e3;
12	const DAY_MS = 24 * HOUR_MS;
13	
14	// Sunday opens the week, matching Date#getUTCDay's own 0.
15	const SUNDAY = 0;
16	
17	// When `frequency`'s current period opened, as a Date, or null for `manual`, which has
18	// no period at all. THE PERIOD IS THE UTC CALENDAR and nothing a repo configures
19	// (#1995): a day opens at midnight UTC, a week on the Sunday that opened it, a month
20	// on its 1st.
21	export function mostRecentAnchor(frequency, now) {
22	  const at = new Date(now);
23	  if (frequency === 'manual') return null;
24	  const midnight = Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate());
25	  if (frequency === 'daily') return new Date(midnight);
26	  if (frequency === 'weekly') return new Date(midnight - ((at.getUTCDay() - SUNDAY + 7) % 7) * DAY_MS);
27	  if (frequency === 'monthly') return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), 1));
28	  throw new Error(`unknown frequency "${frequency}"`);
29	}
30	
31	// --- the cadence terms ----------------------------------------------------------
32	// How a task states WHEN it runs, inside its own `preconditions`: the queue keeps no
33	// calendar of its own, so the cadence is one of the task's conditions.
34	//
35	//   schedule:at-most-<daily|weekly|monthly>   no run created or closed since this
36	//                                             UTC period opened
37	//
38	// Whether a task is asked at all is its `trigger`, not the shape of this list: a
39	// task nothing asks may still state conditions, which are judged when somebody
40	// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
41	//
42	export const CADENCES = ['daily', 'weekly', 'monthly'];
43	export const ALTERNATIVE_SEPARATOR = '||';
44	export const SCHEDULE_TERM = 'schedule';
45	export const AT_MOST_PREFIX = 'at-most-';
46	export const NOT_FAILED_TERM = 'last-run-not-failed';
47	export const NOT_PARKED_TERM = 'last-run-not-parked';
48	
49	export const scheduleTermFor = (cadence) => `${SCHEDULE_TERM}:${AT_MOST_PREFIX}${cadence}`;
